head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST35400";
scwin.dtree = undefined;
scwin.contn = null;
scwin.keyword = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.contn = "${fn:replace(sysInfo.contn, \"\"\", \"\\\"\")}";
        scwin.keyword = "${fn:replace(param.keyword, \"\"\", \"\\\"\")}";
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst35400.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword"))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jlddst35400: 진입 키 explanationsystem 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_keyword_onkeypress
 * @description ipt_keyword onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_keyword_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        scwin.keyEvent(event)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst35400.ipt_keyword_onkeypress' }); }
};

/**
 * @method
 * @name btn_fnSearch_onclick
 * @description btn_fnSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnSearch_onclick = function(e){
    try {
        scwin.fnSearch(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst35400.btn_fnSearch_onclick' }); }
};

/**
 * @method
 * @name grd_sysInfoList_oncellclick
 * @description grd_sysInfoList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_sysInfoList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_sysInfoList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_sysInfoList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_ViewSysInfo('${sysInfo.helpClssId}'); return false; (EL 미해석) */
        return false; return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_sysInfoList.oncellclick' });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_ViewSysInfo_xhr
 * @description View Sys Info xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ViewSysInfo_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ViewSysInfo_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ViewSysInfo_xhr", unresolved: "action:self_submit:tx_fn_ViewSysInfo_xhr" };
};

/**
 * @method
 * @name viewSysInfo
 * @description view Sys Info 처리
 * @param {String} ipt_sysInfoClssId ipt_sysInfoClssId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewSysInfo = async function (ipt_sysInfoClssId) {
    $c.util.getComponent("dma_ViewSysInfoXhrReq").set("sysInfoClssId", ipt_sysInfoClssId);
    const result = await scwin.tx_fn_ViewSysInfo_xhr();
    (console.error('[sdd] 이 화면 문서에 #sysInfoContext 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#sysInfoContext")).html(result);
    scwin.dtree.open(ipt_sysInfoClssId);
    scwin.dtree.selected(ipt_sysInfoClssId);
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSearch = function () {
    $("#searchForm").submit();
};

/**
 * @method
 * @name replaceKeyword
 * @description replace Keyword 처리
 * @param {String} srcStr srcStr
 * @param {*} keyword keyword
 * @returns {void}
 * @hidden N
 */
scwin.replaceKeyword = function (srcStr, keyword) {
    document.write(srcStr.replace(new RegExp(keyword, "g"), "<span class='search'>" + keyword + "</span>"));
};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initValue = async function () {
    for (let i = 0; i < scwin.dtree.aNodes.length; i++) {
        if (!scwin.dtree.aNodes[i]._hc) {
            await scwin.viewSysInfo(scwin.dtree.aNodes[i].id);
            break;
        }
    }
};

/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {*} evt evt
 * @returns {void}
 * @hidden N
 */
scwin.keyEvent = function (evt) {
    const evCode = (false) ? evt.which : $c.util.getKeyCode(event);
    if (evCode === 13) {
        scwin.fnSearch();
    }
};

/**
 * @method
 * @name fnPageGo
 * @description fn Page Go 처리
 * @param {*} page page
 * @returns {void}
 * @hidden N
 */
scwin.fnPageGo = function (page) {
    $c.util.getComponent('dma_hiddenStore').set('ipt_pageIndex', page);
    scwin.fnSearch();
};

/**
 * @method
 * @name pageNav
 * @description page Nav 처리
 * @param {*} funcName funcName
 * @param {*} pageNum pageNum
 * @param {*} pageSize pageSize
 * @param {*} total total
 * @returns {void}
 * @hidden N
 */
scwin.pageNav = function (funcName, pageNum, pageSize, total) {
    if (total < 1) {
        return "";
    }
    let ret = "";
    const PAGEBLOCK = 10;
    const totalPages = Math.floor((total - 1) / pageSize) + 1;
    let firstPage = Math.floor((pageNum - 1) / PAGEBLOCK) * PAGEBLOCK + 1;
    if (firstPage <= 0) {
        firstPage = 1;
    }
    let lastPage = firstPage - 1 + PAGEBLOCK;
    if (lastPage > totalPages) {
        lastPage = totalPages;
    }
    if (firstPage > PAGEBLOCK) {
        ret += scwin.navAnchor(funcName, 1, "<<처음") + "&nbsp;\n";
        ret += scwin.navAnchor(funcName, (firstPage - 1), "<이전") + "&nbsp;\n";
    }
    for (i = firstPage; i <= lastPage; i++) {
        if (pageNum === i) {
            ret += "<a class='active' onclick='return false;' href='#page_link_" + 1 + "'>" + i + "</a>&nbsp;\n";
        } else {
            ret += scwin.navAnchor(funcName, i, i) + "&nbsp;\n";
        }
    }
    if (lastPage < totalPages) {
        ret += scwin.navAnchor(funcName, (lastPage + 1), "다음>") + "&nbsp;\n";
        ret += "&nbsp;" + scwin.navAnchor(funcName, totalPages, "끝>>") + "\n";
    }
    return ret;
};

/**
 * @method
 * @name navAnchor
 * @description nav Anchor 처리
 * @param {*} funcName funcName
 * @param {*} pageNo pageNo
 * @param {*} anchorText anchorText
 * @returns {void}
 * @hidden N
 */
scwin.navAnchor = function (funcName, pageNo, anchorText) {
    return "<a onclick='" + funcName + "(" + pageNo + ");return false;' href='#page_link_" + anchorText + "'>" + anchorText + "</a>";
};
